 const proof=await feeObservation(f);assert.equal((await recordCheckoutFeeInspection(f.database,proof.input)).status,'recorded');const payee=await f.made('finance/payees',{kind:'organization',code:'FEEPROVIDER',name:'Synthetic processor fee supplier',legalName:'Synthetic Fee Supplier',reason:'Explicit reviewer-selected supplier,not provider identity verification'}),account=(code:string,kind:string,role:string)=>f.made('finance/accounts',{code,name:'Synthetic '+code,kind,operationalRole:role,hubId:f.hub,currencyId:f.currency.id,currencyVersion:1,reason:'Synthetic fee accounts'}),ap=await account('FEEAP','liability','payable'),expense=await account('FEECOST','expense','expense'),tax=await f.made('finance/tax-codes',{code:'FEENOTAX',name:'Synthetic explicit no tax',hubId:f.hub,countryCode:'CA',classification:'out_of_scope',ratePercent:'0',startsOn:'2026-01-01',legalBasis:'Synthetic test only,not tax advice',reason:'No provider label inferred as tax eligibility'});
