 assert.equal((await f.pg.query('SELECT count(*)::integer n FROM public.provider_refund_postings')).rows[0].n,0);assert.equal((await f.pg.query('SELECT current_minor::text amount FROM public.collector_fund_balance($1,$2,$3)',[r.c.collector.id,r.c.holding.id,'2026-11-09'])).rows[0].amount,'5000');assert.equal((await r.post()).response.status,201);
