check('refund headers reserve wallet credit and custody before their journal exists;ordinary reversal cannot bypass source accounting',async f=>{
 const r=await refundAccounting(f);await f.pg.exec("CREATE TABLE public.test_refund_reservation(credit numeric,custody numeric,journal_exists boolean);GRANT INSERT ON public.test_refund_reservation TO kavosh_runtime;CREATE FUNCTION public.test_refund_reservation() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE c record;BEGIN SELECT * INTO c FROM public.provider_collections WHERE academy_id=NEW.academy_id AND id=NEW.collection_id;INSERT INTO public.test_refund_reservation SELECT (public.dated_customer_credit_source(c.id,c.invoice_id,'2026-11-09T12:00:00Z')->>'remainingMinor')::numeric,(SELECT current_minor FROM public.collector_fund_balance(c.collector_id,c.holding_account,'2026-11-09')),EXISTS(SELECT 1 FROM public.finance_journals WHERE id=NEW.id);RETURN NULL;END $$;CREATE TRIGGER test_refund_reservation AFTER INSERT ON public.provider_refund_postings FOR EACH ROW EXECUTE FUNCTION public.test_refund_reservation()");const posted=await r.post();assert.equal(posted.response.status,201,JSON.stringify(posted.body));assert.deepEqual((await f.pg.query('SELECT credit::text,custody::text,journal_exists FROM public.test_refund_reservation')).rows,[{credit:'4900',custody:'4900',journal_exists:false}]);assert.equal((await f.request('finance/journals/'+posted.body.data.id+'/reverse',{periodId:f.period.id,periodVersion:1,postedOn:'2026-11-09',description:'Use dedicated source correction',reason:'Do not erase refund accounting'})).body.error.code,'PROVIDER_REFUND_CORRECTION_WORKFLOW_REQUIRED');
});
