if(process.env.TEST_DATABASE_URL)check('refund evidence commits before a competing credit application can pass the shared provider lock',async f=>{
 const c=await creditApplication(f),{input}=await refundObservation(f),barrier=await f.pg.runtime!.connect();let refund:ReturnType<typeof recordCheckoutRefundInspection>|undefined,application:ReturnType<typeof f.request>|undefined;
 async function waiting(fragment:string){const until=Date.now()+3000;while(Date.now()<until){if((await f.pg.query<{n:number}>("SELECT count(*)::integer n FROM pg_stat_activity WHERE datname=current_database() AND pid<>pg_backend_pid() AND wait_event='advisory' AND position($1 in query)>0",[fragment])).rows[0].n>0)return true;await delay(10);}return false;}
 try{await barrier.query('BEGIN');await barrier.query("SELECT pg_advisory_xact_lock(hashtextextended($1||':test-refund-barrier',0))",[f.a]);await f.pg.exec("CREATE FUNCTION public.test_refund_commit_barrier() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN IF NEW.event_type='checkout.refunds.review_required.critical' THEN PERFORM pg_advisory_xact_lock(hashtextextended(NEW.academy_id::text||':test-refund-barrier',0));END IF;RETURN NEW;END $$;CREATE TRIGGER test_refund_commit_barrier BEFORE INSERT ON public.outbox_events FOR EACH ROW EXECUTE FUNCTION public.test_refund_commit_barrier()");
  refund=recordCheckoutRefundInspection(f.database,input);assert.equal(await waiting('record_checkout_refund_inspection'),true);application=f.request(c.path,c.input);assert.equal(await waiting('checkout-provider:'),true);await barrier.query('COMMIT');assert.equal((await refund).status,'recorded');const result=await application;assert.equal(result.response.status,409,JSON.stringify(result.body));assert.equal(result.body.error.code,'CUSTOMER_CREDIT_PROVIDER_REVIEW_REQUIRED');assert.equal((await f.pg.query('SELECT count(*)::integer n FROM public.customer_credit_applications')).rows[0].n,0);
 }finally{await barrier.query('ROLLBACK');barrier.release();await refund?.catch(()=>{});await application?.catch(()=>{});await f.pg.exec('DROP TRIGGER IF EXISTS test_refund_commit_barrier ON public.outbox_events;DROP FUNCTION IF EXISTS public.test_refund_commit_barrier()');}
});
